(()=>{const icons={"Death Row":"data:image/png;base64,"};function mount(){if(!document.getElementById("legacy-navigation-fit")){const style=document.createElement("style");style.id="legacy-navigation-fit";style.textContent="#final-site-shell nav.topnav>button.final-menu-unavailable{display:inline-flex;align-items:center;gap:8px;border:0;background:transparent;opacity:.46;color:inherit;font:inherit;padding:10px 14px;text-align:left}#final-site-shell nav.topnav>button.final-menu-unavailable img{width:34px;height:34px;object-fit:contain}#final-site-shell nav.topnav>button.final-menu-unavailable span{display:flex;flex-direction:column;gap:3px}#final-site-shell nav.topnav>button.final-menu-unavailable small{font-size:10px;letter-spacing:.4px}";document.head.append(style)}const nav=document.querySelector('#final-site-shell .final-site-nav,#final-site-shell nav.topnav,#final-site-shell nav[aria-label="Main navigation"]');if(!nav)return;let power=[...nav.querySelectorAll('a,button')].find(e=>/powergamers/i.test(e.textContent));if(!power){power=document.createElement('a');power.href='https://relichub.github.io/powergamers/';power.innerHTML='<img src="https://relichub.github.io/powergamers/powergamers-icon.png" alt=""><span>Powergamers</span>';nav.append(power)}if(power?.tagName==='BUTTON'){const a=document.createElement('a');a.href='https://relichub.github.io/powergamers/';a.innerHTML=power.innerHTML; a.querySelectorAll('small').forEach(e=>e.remove());power.replaceWith(a);power=a}if(power){power.classList.remove('final-menu-unavailable');power.removeAttribute('disabled');power.href='https://relichub.github.io/powergamers/'}let death=[...nav.querySelectorAll('a,button')].find(e=>e.href?.includes('/death-row')||/death row/i.test(e.textContent));if(!death){death=document.createElement('a');death.href='https://relichub.xyz/death-row/';death.innerHTML='<img src="'+icons['Death Row']+'" alt=""><span>Death Row</span>';nav.append(death)}if(death.tagName==='A'){death.classList.remove('final-menu-unavailable');death.href='https://relichub.xyz/death-row/'}let insomnia=[...nav.querySelectorAll('a,button')].find(e=>/insomniac/i.test(e.textContent));if(!insomnia){insomnia=document.createElement('button');insomnia.disabled=true;insomnia.className='final-menu-unavailable';insomnia.innerHTML='<img src="https://relichub.github.io/powergamers/insomniac-icon.png" alt=""><span>Insomniac<small>Coming soon</small></span>';death.before(insomnia)}if(power&&insomnia&&power.nextElementSibling!==insomnia&&power.parentElement===insomnia.parentElement)insomnia.before(power)}mount();new MutationObserver(mount).observe(document.body,{childList:true,subtree:true})})();